WITH cleaned AS (SELECT *, FLOOR(temp_c) AS temp_c_whole FROM device_readings WHERE HOUR(reading_ts) BETWEEN 11 AND 18), flagged AS (SELECT *, CASE WHEN LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts ASC, id ASC) IS NULL OR reading_ts > LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts ASC, id ASC) + INTERVAL '30' MINUTE THEN 1 ELSE 0 END AS is_new_burst FROM cleaned), sessionized AS (SELECT *, SUM(is_new_burst) OVER (PARTITION BY device_code ORDER BY reading_ts ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM flagged) SELECT DATE_TRUNC('DAY', reading_ts) AS activity_day, DATE_TRUNC('HOUR', reading_ts) AS hour_window, COUNT(DISTINCT id) AS distinct_ids, BIT_OR(status_bits) AS status_bits_bit_or, MIN(reading_ts) AS first_reading_ts, CORR(humidity, temp_c) AS corr_humidity_temp_c, GROUPING_ID() AS grouping_level FROM sessionized GROUP BY CUBE (DATE_TRUNC('DAY', reading_ts), DATE_TRUNC('HOUR', reading_ts));
